css:
.left{
    text-align: left;
}

.right{
    text-align: right;
}

.center{
    text-align: center;
}

.emp-table {
    font-family: 'Times New Roman', serif;
    font-size: 14px;
    color: black;
    border: 1px solid black;
    border-collapse: collapse;
}

.emp-table td, .emp-table th,
.emp-table tr {
    border: 1px solid black;
}

.table-wrapper {
    display: flex;
    gap: 10px;           /* space between tables */
    align-items: flex-start;
}
